-- 1. ENUM TYPES
CREATE TYPE public.app_role AS ENUM ('admin', 'confirmateur', 'stock_manager');
CREATE TYPE public.customer_status AS ENUM ('new', 'regular', 'vip', 'blacklisted');
CREATE TYPE public.delivery_type AS ENUM ('home', 'stop_desk');
CREATE TYPE public.order_source AS ENUM ('facebook', 'instagram', 'website', 'phone', 'other');
CREATE TYPE public.order_status AS ENUM ('new','validated','confirmed','cancelled','failed_1','failed_2','failed_3','no_answer','wrong_number','postponed','to_reconfirm','callback','duplicate','out_of_stock','shipped','delivered','returned','exchange','ready','at_station','preparing','delivered_paid','erreur','to_station','au_bureau','Échec_de_livraison','en_livraison','alerte');
CREATE TYPE public.stock_movement_type AS ENUM ('entry', 'exit', 'adjustment', 'sale', 'return');

-- 2. TABLES
CREATE TABLE public.profiles (id uuid NOT NULL PRIMARY KEY, email text, full_name text, avatar_url text, is_approved boolean DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.user_roles (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, user_id uuid NOT NULL, role app_role NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.customers (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, name text NOT NULL, phone text NOT NULL, wilaya text NOT NULL, commune text, address text, notes text, status customer_status NOT NULL DEFAULT 'new', total_orders integer NOT NULL DEFAULT 0, total_spent numeric NOT NULL DEFAULT 0, last_order_date timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.products (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, sku text NOT NULL, name text NOT NULL, category text NOT NULL, description text, purchase_price numeric NOT NULL DEFAULT 0, selling_price numeric NOT NULL DEFAULT 0, current_stock integer NOT NULL DEFAULT 0, reserved_stock integer NOT NULL DEFAULT 0, reorder_level integer NOT NULL DEFAULT 10, barcode text, free_delivery boolean NOT NULL DEFAULT false, delivery_pricing_tier text NOT NULL DEFAULT 'standard', custom_home_delivery_fee numeric, custom_stop_desk_fee numeric, average_purchase_price numeric DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.product_variants (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, product_id uuid NOT NULL REFERENCES public.products(id), name text NOT NULL, variant_type text NOT NULL, stock integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.orders (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, order_number text NOT NULL, customer_id uuid REFERENCES public.customers(id), customer_name text NOT NULL, customer_phone text NOT NULL, customer_address text NOT NULL, wilaya text NOT NULL, commune text, source order_source NOT NULL DEFAULT 'other', status order_status NOT NULL DEFAULT 'new', delivery_type delivery_type NOT NULL DEFAULT 'home', total_price numeric NOT NULL DEFAULT 0, delivery_fee numeric NOT NULL DEFAULT 0, discount numeric NOT NULL DEFAULT 0, assigned_agent text, delivery_company text, tracking_number text, notes text, remarks text, alert text, confirmed_at timestamptz, shipped_at timestamptz, delivered_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.order_items (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, order_id uuid NOT NULL REFERENCES public.orders(id), product_id uuid REFERENCES public.products(id), product_name text NOT NULL, variant text, quantity integer NOT NULL DEFAULT 1, unit_price numeric NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.order_history (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, order_id uuid NOT NULL REFERENCES public.orders(id), old_status order_status, new_status order_status NOT NULL, changed_by text, changed_by_user_id uuid, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.deliveries (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, order_id uuid REFERENCES public.orders(id), tracking_number text, carrier text DEFAULT 'zr_express', delivery_status text DEFAULT 'preparing', last_update timestamptz DEFAULT now(), created_at timestamptz DEFAULT now());
CREATE TABLE public.alerts (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, order_id uuid REFERENCES public.orders(id), type text NOT NULL, message text NOT NULL, is_read boolean DEFAULT false, created_at timestamptz DEFAULT now());
CREATE TABLE public.delivery_fees (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, wilaya_code text NOT NULL, wilaya_name text NOT NULL, home_delivery_fee numeric NOT NULL DEFAULT 0, stop_desk_fee numeric NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.special_delivery_fees (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, wilaya_code text NOT NULL, wilaya_name text NOT NULL, home_delivery_fee numeric NOT NULL DEFAULT 0, stop_desk_fee numeric NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.special_delivery_fees_2 (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, wilaya_code text NOT NULL, wilaya_name text NOT NULL, home_delivery_fee numeric NOT NULL DEFAULT 0, stop_desk_fee numeric NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.delivery_company_fees (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, delivery_company text NOT NULL, wilaya_code text NOT NULL, wilaya_name text NOT NULL, home_delivery_fee numeric NOT NULL DEFAULT 0, stop_desk_fee numeric NOT NULL DEFAULT 0, return_fee numeric NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.delivery_promotions (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, name text NOT NULL, description text, discount_type text NOT NULL, discount_value numeric NOT NULL DEFAULT 0, applies_to text NOT NULL, is_active boolean NOT NULL DEFAULT true, start_date timestamptz NOT NULL DEFAULT now(), end_date timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.integrations (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, integration_type text NOT NULL, name text NOT NULL, api_key text, api_secret text, webhook_url text, spreadsheet_id text, store_url text, is_enabled boolean NOT NULL DEFAULT false, settings jsonb DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.meta_integration (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, app_id text, app_secret_encrypted text, page_id text, page_access_token_encrypted text, verify_token text NOT NULL, is_connected boolean NOT NULL DEFAULT false, facebook_connected boolean NOT NULL DEFAULT false, instagram_connected boolean NOT NULL DEFAULT false, auto_reply_messages boolean NOT NULL DEFAULT true, auto_reply_comments boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.meta_pages (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, integration_id uuid REFERENCES public.meta_integration(id), page_id text NOT NULL, page_name text NOT NULL, platform text NOT NULL, page_access_token text, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.google_tokens (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, user_id uuid NOT NULL, access_token text NOT NULL, refresh_token text, token_type text DEFAULT 'Bearer', scope text, email text, expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.assignment_rules (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, rule_type text NOT NULL, agent_name text NOT NULL, match_value text NOT NULL, priority integer NOT NULL DEFAULT 0, is_active boolean NOT NULL DEFAULT true, days_of_week integer[] DEFAULT '{}'::integer[], start_hour integer DEFAULT 0, end_hour integer DEFAULT 23, start_date timestamptz, end_date timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.assignment_settings (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, setting_key text NOT NULL, setting_value jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.automation_settings (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, setting_key text NOT NULL, setting_value jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.auto_confirmation_logs (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, order_id uuid REFERENCES public.orders(id), order_number text NOT NULL, customer_phone text NOT NULL, ai_decision text NOT NULL, ai_reason text, checks_result jsonb DEFAULT '{}'::jsonb, whatsapp_message_sent boolean DEFAULT false, whatsapp_response text, customer_reply text, final_status text, conversation_status text DEFAULT 'pending', conversation_history jsonb DEFAULT '[]'::jsonb, last_message_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.stock_movements (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, product_id uuid NOT NULL REFERENCES public.products(id), movement_type stock_movement_type NOT NULL, quantity integer NOT NULL, previous_stock integer NOT NULL, new_stock integer NOT NULL, reason text, reference text, purchase_price numeric, created_by uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.local_livreurs (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, name text NOT NULL, phone text NOT NULL, wilaya text, tarif numeric NOT NULL DEFAULT 0, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());

